/bin/zsh -lc "python3 -c 'import json,itertools
from collections import defaultdict
with open(\"input.json\") as f: d=json.load(f)
def reach(s,t,removed=frozenset()):
    adj=defaultdict(list)
    for e in d[\"edges\"]:
        if e[\"id\"] not in removed: adj[e[\"source\"]].append(e[\"target\"])
    seen={s}; todo=[s]
    while todo:
        v=todo.pop()
        if v==t: return True
        for w in adj[v]:
            if w not in seen: seen.add(w); todo.append(w)
    return False
reachable=[]; authorized=[]
for p in sorted(d[\"probes\"],key=lambda p:p[\"id\"]):
    r=reach(p[\"source\"],p[\"target\"])
    if r: reachable.append(p[\"id\"])
    if r and p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and d[\"now\"]<p[\"expires\"] and p[\"key\"] not in d[\"revoked_keys\"]: authorized.append(p[\"id\"])
rem=sorted((e for e in d[\"edges\"] if e[\"removable\"]),key=lambda e:e[\"id\"])
best=None; feasible=0
for bits in itertools.product((False,True),repeat=len(rem)):
    removed={e[\"id\"] for e,b in zip(rem,bits) if b}
    if any(reach(s,t,removed) for s,t in d[\"forbidden\"]): continue
    if not all(reach(s,t,removed) for s,t in d[\"required\"]): continue
    feasible+=1
    key=(sum(e[\"cost\"] for e,b in zip(rem,bits) if b),len(removed),sorted(removed))
    if best is None or key<best: best=key
print(json.dumps({\"reachable_probes\":reachable,\"authorized_probes\":authorized,\"repair_edges\":best[2],\"repair_cost\":best[0]}))
print(json.dumps({\"subsets_checked\":2**len(rem),\"feasible_subsets\":feasible,\"objective\":best}))'"

